"""Cheapest Flights Within K Stops — Bellman-Ford limited to k+1 rounds.

Relaxing from a snapshot of the previous round is what enforces the stop limit;
plain Dijkstra would happily take a cheaper path with too many hops.

Time: O(k * E)   Space: O(n)
"""
from typing import List


class Solution:
    def findCheapestPrice(self, n: int, flights: List[List[int]], src: int,
                          dst: int, k: int) -> int:
        INF = float("inf")
        dist = [INF] * n
        dist[src] = 0
        for _ in range(k + 1):
            snapshot = dist[:]
            for u, v, price in flights:
                if snapshot[u] + price < dist[v]:
                    dist[v] = snapshot[u] + price
        return -1 if dist[dst] == INF else dist[dst]
